@Test
@SuppressWarnings("unchecked")
public void testLongToIntegerConversion() {
    StructType struct = StructType.of(required(17, "i", Types.IntegerType.get()));
    UnboundPredicate<Long> lt = new UnboundPredicate<>(LT, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Less than above max should be alwaysTrue", Expressions.alwaysTrue(), lt.bind(struct));
    UnboundPredicate<Long> lteq = new UnboundPredicate<>(LT_EQ, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Less than or equal above max should be alwaysTrue", Expressions.alwaysTrue(), lteq.bind(struct));
    UnboundPredicate<Long> gt = new UnboundPredicate<>(GT, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Greater than below min should be alwaysTrue", Expressions.alwaysTrue(), gt.bind(struct));
    UnboundPredicate<Long> gteq = new UnboundPredicate<>(GT_EQ, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Greater than or equal below min should be alwaysTrue", Expressions.alwaysTrue(), gteq.bind(struct));
    UnboundPredicate<Long> gtMax = new UnboundPredicate<>(GT, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Greater than above max should be alwaysFalse", Expressions.alwaysFalse(), gtMax.bind(struct));
    UnboundPredicate<Long> gteqMax = new UnboundPredicate<>(GT_EQ, ref("i"), (long) Integer.MAX_VALUE + 1L);
    Assert.assertEquals("Greater than or equal above max should be alwaysFalse", Expressions.alwaysFalse(), gteqMax.bind(struct));
    UnboundPredicate<Long> ltMin = new UnboundPredicate<>(LT, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Less than below min should be alwaysFalse", Expressions.alwaysFalse(), ltMin.bind(struct));
    UnboundPredicate<Long> lteqMin = new UnboundPredicate<>(LT_EQ, ref("i"), (long) Integer.MIN_VALUE - 1L);
    Assert.assertEquals("Less than or equal below min should be alwaysFalse", Expressions.alwaysFalse(), lteqMin.bind(struct));
    Expression ltExpr = new UnboundPredicate<>(LT, ref("i"), (long) Integer.MAX_VALUE).bind(struct, true);
    BoundPredicate<Integer> ltMax = assertAndUnwrap(ltExpr);
    Assert.assertTrue("Should be a literal predicate", ltMax.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MAX_VALUE, ltMax.asLiteralPredicate().literal().value());
    Expression lteqExpr = new UnboundPredicate<>(LT_EQ, ref("i"), (long) Integer.MAX_VALUE).bind(struct);
    BoundPredicate<Integer> lteqMax = assertAndUnwrap(lteqExpr);
    Assert.assertTrue("Should be a literal predicate", lteqMax.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MAX_VALUE, lteqMax.asLiteralPredicate().literal().value());
    Expression gtExpr = new UnboundPredicate<>(GT, ref("i"), (long) Integer.MIN_VALUE).bind(struct);
    BoundPredicate<Integer> gtMin = assertAndUnwrap(gtExpr);
    Assert.assertTrue("Should be a literal predicate", gtMin.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MIN_VALUE, gtMin.asLiteralPredicate().literal().value());
    Expression gteqExpr = new UnboundPredicate<>(GT_EQ, ref("i"), (long) Integer.MIN_VALUE).bind(struct);
    BoundPredicate<Integer> gteqMin = assertAndUnwrap(gteqExpr);
    Assert.assertTrue("Should be a literal predicate", gteqMin.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Integer", (Integer) Integer.MIN_VALUE, gteqMin.asLiteralPredicate().literal().value());
}

@Test
@SuppressWarnings("unchecked")
public void testDoubleToFloatConversion() {
    StructType struct = StructType.of(required(18, "f", Types.FloatType.get()));
    UnboundPredicate<Double> lt = new UnboundPredicate<>(LT, ref("f"), (double) Float.MAX_VALUE * 2);
    Assert.assertEquals("Less than above max should be alwaysTrue", Expressions.alwaysTrue(), lt.bind(struct));
    UnboundPredicate<Double> lteq = new UnboundPredicate<>(LT_EQ, ref("f"), (double) Float.MAX_VALUE * 2);
    Assert.assertEquals("Less than or equal above max should be alwaysTrue", Expressions.alwaysTrue(), lteq.bind(struct));
    UnboundPredicate<Double> gt = new UnboundPredicate<>(GT, ref("f"), (double) Float.MAX_VALUE * -2);
    Assert.assertEquals("Greater than below min should be alwaysTrue", Expressions.alwaysTrue(), gt.bind(struct));
    UnboundPredicate<Double> gteq = new UnboundPredicate<>(GT_EQ, ref("f"), (double) Float.MAX_VALUE * -2);
    Assert.assertEquals("Greater than or equal below min should be alwaysTrue", Expressions.alwaysTrue(), gteq.bind(struct));
    UnboundPredicate<Double> gtMax = new UnboundPredicate<>(GT, ref("f"), (double) Float.MAX_VALUE * 2);
    Assert.assertEquals("Greater than above max should be alwaysFalse", Expressions.alwaysFalse(), gtMax.bind(struct));
    UnboundPredicate<Double> gteqMax = new UnboundPredicate<>(GT_EQ, ref("f"), (double) Float.MAX_VALUE * 2);
    Assert.assertEquals("Greater than or equal above max should be alwaysFalse", Expressions.alwaysFalse(), gteqMax.bind(struct));
    UnboundPredicate<Double> ltMin = new UnboundPredicate<>(LT, ref("f"), (double) Float.MAX_VALUE * -2);
    Assert.assertEquals("Less than below min should be alwaysFalse", Expressions.alwaysFalse(), ltMin.bind(struct));
    UnboundPredicate<Double> lteqMin = new UnboundPredicate<>(LT_EQ, ref("f"), (double) Float.MAX_VALUE * -2);
    Assert.assertEquals("Less than or equal below min should be alwaysFalse", Expressions.alwaysFalse(), lteqMin.bind(struct));
    Expression ltExpr = new UnboundPredicate<>(LT, ref("f"), (double) Float.MAX_VALUE).bind(struct);
    BoundPredicate<Float> ltMax = assertAndUnwrap(ltExpr);
    Assert.assertTrue("Should be a literal predicate", ltMax.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Float", (Float) Float.MAX_VALUE, ltMax.asLiteralPredicate().literal().value());
    Expression lteqExpr = new UnboundPredicate<>(LT_EQ, ref("f"), (double) Float.MAX_VALUE).bind(struct);
    BoundPredicate<Float> lteqMax = assertAndUnwrap(lteqExpr);
    Assert.assertTrue("Should be a literal predicate", lteqMax.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Float", (Float) Float.MAX_VALUE, lteqMax.asLiteralPredicate().literal().value());
    Expression gtExpr = new UnboundPredicate<>(GT, ref("f"), (double) -Float.MAX_VALUE).bind(struct);
    BoundPredicate<Float> gtMin = assertAndUnwrap(gtExpr);
    Assert.assertTrue("Should be a literal predicate", gtMin.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Float", Float.valueOf(-Float.MAX_VALUE), gtMin.asLiteralPredicate().literal().value());
    Expression gteqExpr = new UnboundPredicate<>(GT_EQ, ref("f"), (double) -Float.MAX_VALUE).bind(struct);
    BoundPredicate<Float> gteqMin = assertAndUnwrap(gteqExpr);
    Assert.assertTrue("Should be a literal predicate", gteqMin.isLiteralPredicate());
    Assert.assertEquals("Should translate bound to Float", Float.valueOf(-Float.MAX_VALUE), gteqMin.asLiteralPredicate().literal().value());
}

