@Test
public void testSpecValues() {
    Assert.assertEquals("Spec example: hash(true) = 1392991556", 1392991556, Bucket.<Integer>get(Types.IntegerType.get(), 100).hash(1));
    Assert.assertEquals("Spec example: hash(34) = 2017239379", 2017239379, Bucket.<Integer>get(Types.IntegerType.get(), 100).hash(34));
    Assert.assertEquals("Spec example: hash(34L) = 2017239379", 2017239379, Bucket.<Long>get(Types.LongType.get(), 100).hash(34L));
    Assert.assertEquals("Spec example: hash(17.11F) = -142385009", -142385009, new Bucket.BucketFloat(100).hash(1.0F));
    Assert.assertEquals("Spec example: hash(17.11D) = -142385009", -142385009, new Bucket.BucketDouble(100).hash(1.0D));
    Assert.assertEquals("Spec example: hash(decimal2(14.20)) = -500754589", -500754589, Bucket.<BigDecimal>get(Types.DecimalType.of(9, 2), 100).hash(new BigDecimal("14.20")));
    Assert.assertEquals("Spec example: hash(decimal2(14.20)) = -500754589", -500754589, Bucket.<BigDecimal>get(Types.DecimalType.of(9, 2), 100).hash(new BigDecimal("14.20")));
    Literal<Integer> date = Literal.of("2017-11-16").to(Types.DateType.get());
    Assert.assertEquals("Spec example: hash(2017-11-16) = -653330422", -653330422, Bucket.<Integer>get(Types.DateType.get(), 100).hash(date.value()));
    Literal<Long> timeValue = Literal.of("22:31:08").to(Types.TimeType.get());
    Assert.assertEquals("Spec example: hash(22:31:08) = -662762989", -662762989, Bucket.<Long>get(Types.TimeType.get(), 100).hash(timeValue.value()));
    Literal<Long> timestampVal = Literal.of("2017-11-16T22:31:08").to(Types.TimestampType.withoutZone());
    Assert.assertEquals("Spec example: hash(2017-11-16T22:31:08) = -2047944441", -2047944441, Bucket.<Long>get(Types.TimestampType.withoutZone(), 100).hash(timestampVal.value()));
    Literal<Long> timestamptzVal = Literal.of("2017-11-16T14:31:08-08:00").to(Types.TimestampType.withZone());
    Assert.assertEquals("Spec example: hash(2017-11-16T14:31:08-08:00) = -2047944441", -2047944441, Bucket.<Long>get(Types.TimestampType.withZone(), 100).hash(timestamptzVal.value()));
    Assert.assertEquals("Spec example: hash(\"iceberg\") = 1210000089", 1210000089, Bucket.<String>get(Types.StringType.get(), 100).hash("iceberg"));
    Assert.assertEquals("Spec example: hash(\"iceberg\") = 1210000089", 1210000089, Bucket.<Utf8>get(Types.StringType.get(), 100).hash(new Utf8("iceberg")));
    Literal<UUID> uuid = Literal.of("f79c3e09-677c-4bbd-a479-3f349cb785e7").to(Types.UUIDType.get());
    Assert.assertEquals("Spec example: hash(f79c3e09-677c-4bbd-a479-3f349cb785e7) = 1488055340", 1488055340, Bucket.<UUID>get(Types.UUIDType.get(), 100).hash(uuid.value()));
    ByteBuffer bytes = ByteBuffer.wrap(new byte[] { 0, 1, 2, 3 });
    Assert.assertEquals("Spec example: hash([00 01 02 03]) = -188683207", -188683207, Bucket.<ByteBuffer>get(Types.BinaryType.get(), 100).hash(bytes));
    Assert.assertEquals("Spec example: hash([00 01 02 03]) = -188683207", -188683207, Bucket.<ByteBuffer>get(Types.BinaryType.get(), 100).hash(bytes));
}

