@Test
public void testRequiredMapValue() {
    Schema write = new Schema(required(0, "map_field", Types.MapType.ofOptional(1, 2, Types.StringType.get(), Types.IntegerType.get())));
    Schema read = new Schema(required(0, "map_field", Types.MapType.ofRequired(1, 2, Types.StringType.get(), Types.IntegerType.get())));
