@Test
@SuppressWarnings("unchecked")
public void testListOfStructsProjection() throws IOException {
    Schema writeSchema = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()), Types.NestedField.optional(22, "points", Types.ListType.ofOptional(21, Types.StructType.of(Types.NestedField.required(19, "x", Types.IntegerType.get()), Types.NestedField.optional(18, "y", Types.IntegerType.get())))));
    Record record = new Record(AvroSchemaUtil.convert(writeSchema, "table"));
    record.put("id", 34L);
    Record p1 = new Record(AvroSchemaUtil.fromOption(AvroSchemaUtil.fromOption(record.getSchema().getField("points").schema()).getElementType()));
    p1.put("x", 1);
    p1.put("y", 2);
    Record p2 = new Record(p1.getSchema());
    p2.put("x", 3);
    p2.put("y", null);
    record.put("points", ImmutableList.of(p1, p2));
    Schema idOnly = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()));
    Record projected = writeAndRead("id_only", writeSchema, idOnly, record);
    Assert.assertEquals("Should contain the correct id value", 34L, (long) projected.get("id"));
    Assert.assertNull("Should not project points list", projected.get("points"));
    projected = writeAndRead("all_points", writeSchema, writeSchema.select("points"), record);
    Assert.assertNull("Should not project id", projected.get("id"));
    Assert.assertEquals("Should project points list", record.get("points"), projected.get("points"));
    projected = writeAndRead("x_only", writeSchema, writeSchema.select("points.x"), record);
    Assert.assertNull("Should not project id", projected.get("id"));
    Assert.assertNotNull("Should project points list", projected.get("points"));
    List<Record> points = (List<Record>) projected.get("points");
    Assert.assertEquals("Should read 2 points", 2, points.size());
    Record projectedP1 = points.get(0);
    Assert.assertEquals("Should project x", 1, (int) projectedP1.get("x"));
    Assert.assertNull("Should not project y", projectedP1.get("y"));
    Record projectedP2 = points.get(1);
    Assert.assertEquals("Should project x", 3, (int) projectedP2.get("x"));
    Assert.assertNull("Should not project y", projectedP2.get("y"));
    projected = writeAndRead("y_only", writeSchema, writeSchema.select("points.y"), record);
    Assert.assertNull("Should not project id", projected.get("id"));
    Assert.assertNotNull("Should project points list", projected.get("points"));
    points = (List<Record>) projected.get("points");
    Assert.assertEquals("Should read 2 points", 2, points.size());
    projectedP1 = points.get(0);
    Assert.assertNull("Should not project x", projectedP1.get("x"));
    Assert.assertEquals("Should project y", 2, (int) projectedP1.get("y"));
    projectedP2 = points.get(1);
    Assert.assertNull("Should not project x", projectedP2.get("x"));
    Assert.assertEquals("Should project null y", null, projectedP2.get("y"));
    Schema yRenamed = new Schema(Types.NestedField.optional(22, "points", Types.ListType.ofOptional(21, Types.StructType.of(Types.NestedField.optional(18, "z", Types.IntegerType.get())))));
    projected = writeAndRead("y_renamed", writeSchema, yRenamed, record);
    Assert.assertNull("Should not project id", projected.get("id"));
    Assert.assertNotNull("Should project points list", projected.get("points"));
    points = (List<Record>) projected.get("points");
    Assert.assertEquals("Should read 2 points", 2, points.size());
    projectedP1 = points.get(0);
    Assert.assertNull("Should not project x", projectedP1.get("x"));
    Assert.assertNull("Should not project y", projectedP1.get("y"));
    Assert.assertEquals("Should project z", 2, (int) projectedP1.get("z"));
    projectedP2 = points.get(1);
    Assert.assertNull("Should not project x", projectedP2.get("x"));
    Assert.assertNull("Should not project y", projectedP2.get("y"));
    Assert.assertEquals("Should project null z", null, projectedP2.get("z"));
}

@Test
public void testPrimitiveTypes() {
    List<Type> primitives = Lists.newArrayList(Types.BooleanType.get(), Types.IntegerType.get(), Types.LongType.get(), Types.FloatType.get(), Types.DoubleType.get(), Types.DateType.get(), Types.TimeType.get(), Types.TimestampType.withZone(), Types.TimestampType.withoutZone(), Types.StringType.get(), Types.UUIDType.get(), Types.FixedType.ofLength(12), Types.BinaryType.get(), Types.DecimalType.of(9, 4));
    List<Schema> avroPrimitives = Lists.newArrayList(Schema.create(Schema.Type.BOOLEAN), Schema.create(Schema.Type.INT), Schema.create(Schema.Type.LONG), Schema.create(Schema.Type.FLOAT), Schema.create(Schema.Type.DOUBLE), LogicalTypes.date().addToSchema(Schema.create(Schema.Type.INT)), LogicalTypes.timeMicros().addToSchema(Schema.create(Schema.Type.LONG)), addAdjustToUtc(LogicalTypes.timestampMicros().addToSchema(Schema.create(Schema.Type.LONG)), true), addAdjustToUtc(LogicalTypes.timestampMicros().addToSchema(Schema.create(Schema.Type.LONG)), false), Schema.create(Schema.Type.STRING), LogicalTypes.uuid().addToSchema(Schema.createFixed("uuid_fixed", null, null, 16)), Schema.createFixed("fixed_12", null, null, 12), Schema.create(Schema.Type.BYTES), LogicalTypes.decimal(9, 4).addToSchema(Schema.createFixed("decimal_9_4", null, null, 4)));
    for (int i = 0; i < primitives.size(); i += 1) {
        Type type = primitives.get(i);
