    Assert.assertEquals("Should have 1 manifest", 1, delete.manifests().size());
    validateManifestEntries(delete.manifests().get(0), ids(delete.snapshotId(), append.snapshotId(), append.snapshotId()), files(FILE_A, FILE_B, FILE_C), statuses(Status.DELETED, Status.EXISTING, Status.EXISTING));
    table.newDelete().deleteFile(FILE_B).commit();
    Assert.assertEquals("Metadata should be at version 3", 3L, (long) version());
    Snapshot delete2 = readMetadata().currentSnapshot();
    Assert.assertEquals("Should have 1 manifest", 1, delete2.manifests().size());
    validateManifestEntries(delete2.manifests().get(0), ids(delete2.snapshotId(), append.snapshotId()), files(FILE_B, FILE_C), statuses(Status.DELETED, Status.EXISTING));
}

