    // we can fit at most 128Mb/32Mb = 4 files per bin
    TableScan scan = table.newScan().option(TableProperties.SPLIT_OPEN_FILE_COST, String.valueOf(32L * 1024 * 1024));
    Assert.assertEquals(4, Iterables.size(scan.planTasks()));
}

@Test
public void testJsonConversion() throws Exception {
    Schema schema = new Schema(Types.NestedField.required(1, "x", Types.LongType.get()), Types.NestedField.required(2, "y", Types.LongType.get(), "comment"), Types.NestedField.required(3, "z", Types.LongType.get()));
    PartitionSpec spec = PartitionSpec.builderFor(schema).withSpecId(5).build();
    long previousSnapshotId = System.currentTimeMillis() - new Random(1234).nextInt(3600);
    Snapshot previousSnapshot = new BaseSnapshot(ops.io(), previousSnapshotId, null, previousSnapshotId, null, null, ImmutableList.of(new GenericManifestFile(localInput("file:/tmp/manfiest.1.avro"), spec.specId())));
    long currentSnapshotId = System.currentTimeMillis();
    Snapshot currentSnapshot = new BaseSnapshot(ops.io(), currentSnapshotId, previousSnapshotId, currentSnapshotId, null, null, ImmutableList.of(new GenericManifestFile(localInput("file:/tmp/manfiest.2.avro"), spec.specId())));
    List<HistoryEntry> snapshotLog = ImmutableList.<HistoryEntry>builder().add(new SnapshotLogEntry(previousSnapshot.timestampMillis(), previousSnapshot.snapshotId())).add(new SnapshotLogEntry(currentSnapshot.timestampMillis(), currentSnapshot.snapshotId())).build();
    TableMetadata expected = new TableMetadata(null, UUID.randomUUID().toString(), "s3://bucket/test/location", System.currentTimeMillis(), 3, schema, 5, ImmutableList.of(spec), ImmutableMap.of("property", "value"), currentSnapshotId, Arrays.asList(previousSnapshot, currentSnapshot), snapshotLog, ImmutableList.of());
    String asJson = TableMetadataParser.toJson(expected);
    TableMetadata metadata = TableMetadataParser.fromJson(ops.io(), null, JsonUtil.mapper().readValue(asJson, JsonNode.class));
    Assert.assertEquals("Table UUID should match", expected.uuid(), metadata.uuid());
    Assert.assertEquals("Table location should match", expected.location(), metadata.location());
    Assert.assertEquals("Last column ID should match", expected.lastColumnId(), metadata.lastColumnId());
    Assert.assertEquals("Schema should match", expected.schema().asStruct(), metadata.schema().asStruct());
    Assert.assertEquals("Partition spec should match", expected.spec().toString(), metadata.spec().toString());
