@Test
public void testTransactionRewriteManifestsAppendedDirectly() throws IOException {
    Table table = load();
    table.updateProperties().set(TableProperties.SNAPSHOT_ID_INHERITANCE_ENABLED, "true").set(TableProperties.MANIFEST_MIN_MERGE_COUNT, "0").commit();
    table.newFastAppend().appendFile(FILE_A).commit();
