    Assert.assertFalse("Should not read: id below lower bound (5 < 30, 6 < 30). The two sets are disjoint.", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", INT_MIN_VALUE - 2, INT_MIN_VALUE - 1)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertFalse("Should not read: id below lower bound (28 < 30, 29 < 30). The two sets are disjoint.", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", INT_MIN_VALUE - 1, INT_MIN_VALUE)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: id equal to lower bound (30 == 30)", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE - 4, INT_MAX_VALUE - 3)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: in set is a subset of the dictionary", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE, INT_MAX_VALUE + 1)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: id equal to upper bound (79 == 79)", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE + 1, INT_MAX_VALUE + 2)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertFalse("Should not read: id above upper bound (80 > 79, 81 > 79)", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE + 6, INT_MAX_VALUE + 7)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertFalse("Should not read: id above upper bound (85 > 79, 86 > 79). The two sets are disjoint.", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", IntStream.range(INT_MIN_VALUE - 10, INT_MAX_VALUE + 10).boxed().collect(Collectors.toList()))).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: the dictionary is a subset of the in set", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("id", IntStream.range(INT_MIN_VALUE, INT_MAX_VALUE + 1).boxed().collect(Collectors.toList()))).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: the dictionary is equal to the in set", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("all_nulls", 1, 2)).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
    Assert.assertTrue("Should read: in on all nulls column (isFallback to be true) ", shouldRead);
    shouldRead = new ParquetDictionaryRowGroupFilter(SCHEMA, in("some_nulls", "aaa", "some")).shouldRead(parquetSchema, rowGroupMetadata, dictionaryStore);
