    Assert.assertTrue("Should read: range matches", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "0st")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: range matches", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "1str1")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: range matches", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "1str1_xgd")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: range matches", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "2str")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: range matches", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "9xstr")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should not read: range doesn't match", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "0S")).shouldRead(parquetSchema, rowGroupMetadata);
