    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "x")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should not read: range doesn't match", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, startsWith("str", "9str9aaa")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should not read: range doesn't match", shouldRead);
}

@Test
public void testIntegerIn() {
    boolean shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("id", INT_MIN_VALUE - 25, INT_MIN_VALUE - 24)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should not read: id below lower bound (5 < 30, 6 < 30)", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("id", INT_MIN_VALUE - 2, INT_MIN_VALUE - 1)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should not read: id below lower bound (28 < 30, 29 < 30)", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("id", INT_MIN_VALUE - 1, INT_MIN_VALUE)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: id equal to lower bound (30 == 30)", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE - 4, INT_MAX_VALUE - 3)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: id between lower and upper bounds (30 < 75 < 79, 30 < 76 < 79)", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE, INT_MAX_VALUE + 1)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: id equal to upper bound (79 == 79)", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE + 1, INT_MAX_VALUE + 2)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should not read: id above upper bound (80 > 79, 81 > 79)", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("id", INT_MAX_VALUE + 6, INT_MAX_VALUE + 7)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should not read: id above upper bound (85 > 79, 86 > 79)", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("all_nulls", 1, 2)).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertFalse("Should skip: in on all nulls column", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("some_nulls", "aaa", "some")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: in on some nulls column", shouldRead);
    shouldRead = new ParquetMetricsRowGroupFilter(SCHEMA, in("no_nulls", "aaa", "")).shouldRead(parquetSchema, rowGroupMetadata);
    Assert.assertTrue("Should read: in on no nulls column", shouldRead);
}

