@Test
public void testNullableWithWriteOption() throws IOException {
    File location = new File(temp.newFolder("parquet"), "test");
    String sourcePath = String.format("%s/nullable_poc/sourceFolder/", location.toString());
    String targetPath = String.format("%s/nullable_poc/targetFolder/", location.toString());
    tableProperties = ImmutableMap.of(TableProperties.WRITE_NEW_DATA_LOCATION, targetPath);
    spark = SparkSession.builder().master("local[2]").appName("NullableTest").getOrCreate();
    // read this and append to iceberg dataset
    spark.read().schema(sparkSchema).json(JavaSparkContext.fromSparkContext(spark.sparkContext()).parallelize(data1)).write().parquet(sourcePath);
    // this is our iceberg dataset to which we will append data
    new HadoopTables(spark.sessionState().newHadoopConf()).create(icebergSchema, PartitionSpec.builderFor(icebergSchema).identity("requiredField").build(), tableProperties, targetPath);
    // this is the initial data inside the iceberg dataset
    spark.read().schema(sparkSchema).json(JavaSparkContext.fromSparkContext(spark.sparkContext()).parallelize(data0)).write().format("iceberg").mode(SaveMode.Append).save(targetPath);
    // read from parquet and append to iceberg w/ nullability check disabled
    spark.read().schema(SparkSchemaUtil.convert(icebergSchema)).parquet(sourcePath).write().format("iceberg").option("check-nullability", false).mode(SaveMode.Append).save(targetPath);
    // read all data
    List<Row> rows = spark.read().format("iceberg").load(targetPath).collectAsList();
