@Test
public void testSparkCanReadUnknownTransform() throws IOException {
    File parent = temp.newFolder("avro");
    File location = new File(parent, "test");
    File dataFolder = new File(location, "data");
    dataFolder.mkdirs();
    HadoopTables tables = new HadoopTables(CONF);
    Table table = tables.create(SCHEMA, UNKNOWN_SPEC, location.toString());
    List<GenericData.Record> expected = RandomData.generateList(table.schema(), 100, 1L);
    File parquetFile = new File(dataFolder, FileFormat.PARQUET.addExtension(UUID.randomUUID().toString()));
    FileAppender<GenericData.Record> writer = Parquet.write(localOutput(parquetFile)).schema(table.schema()).build();
    try {
        writer.addAll(expected);
    } finally {
        writer.close();
    }
    DataFile file = DataFiles.builder(FAKE_SPEC).withInputFile(localInput(parquetFile)).withMetrics(writer.metrics()).withPartitionPath("id_zero=0").build();
    OutputFile manifestFile = localOutput(FileFormat.AVRO.addExtension(temp.newFile().toString()));
    ManifestWriter manifestWriter = ManifestWriter.write(FAKE_SPEC, manifestFile);
    try {
        manifestWriter.add(file);
    } finally {
        manifestWriter.close();
    }
    TableOperations ops = ((HasTableOperations) table).operations();
    ops.commit(ops.current(), ops.current().replaceCurrentSnapshot(new FakeSnapshot(manifestWriter.toManifestFile())));
    Dataset<Row> df = spark.read().format("iceberg").load(location.toString());
    List<Row> rows = df.collectAsList();
    Assert.assertEquals("Should contain 100 rows", 100, rows.size());
    for (int i = 0; i < expected.size(); i += 1) {
        TestHelpers.assertEqualsSafe(table.schema().asStruct(), expected.get(i), rows.get(i));
    }
}

